callGraph.callee:
agents
      .filter(agent => {
        // 只显示已加载完成且没有错误的 Agent
        // 修复：允许没有元数据的Agent显示
        if (!agent.isLoaded || agent.hasError) return false

        const { query, tags, category, pricingType } = filters
        const metadata = agent.metadata

        // 应用类别过滤 — agents without a category are only shown under "all"/"other"
        if (category && category !== 'all') {
          const cat = metadata?.category || 'other'
          if (cat !== category) return false
        }

        // 文本搜索 - 修复：允许通过ID搜索没有元数据的Agent
        if (query.trim()) {
          const searchText = query.toLowerCase().trim()

          // 如果没有元数据，只能通过ID搜索
          if (!metadata) {
            return agent.id.toString().includes(searchText)
          }

          const nameMatch = metadata.name.toLowerCase().includes(searchText)
          const descMatch = metadata.description.toLowerCase().includes(searchText)
          const tagMatch = metadata.tags?.some(tag => 
            tag.toLowerCase().includes(searchText)
          )
          const idMatch = agent.id.toString().includes(searchText)

          if (!nameMatch && !descMatch && !tagMatch && !idMatch) {
            return false
          }
        }

        // 标签过滤 - 修复：没有元数据的Agent不参与标签过滤
        if (tags.length > 0) {
          if (!metadata) return false // 没有元数据的Agent没有标签
          const hasAllTags = tags.every(tag => 
            metadata.tags?.includes(tag)
          )
          if (!hasAllTags) return false
        }

        // 价格类型过滤 - 修复：没有元数据的Agent不参与价格过滤
        if (pricingType !== 'all') {
          if (!metadata || !metadata.pricing) return false
          if (metadata.pricing.type !== pricingType) {
            return false
          }
        }

        return true
      })
      .sort

rawData.map((item: any) => {
    try {
      const subscriptionId = BigInt(item.subscriptionId?.toString() || '0')
      const planId = BigInt(item.planId?.toString() || '0')
      const agentId = BigInt(item.agentId?.toString() || '0')

      // 确保 subscriber 是有效的 0x${string} 类型
      let subscriber: `0x${string}`
      if (item.subscriber && typeof item.subscriber === 'string' && item.subscriber.startsWith('0x')) {
        subscriber = item.subscriber as `0x${string}`
      } else {
        subscriber = '0x0000000000000000000000000000000000000000'
      }

      const status = Number(item.status) as SubscriptionStatus
      const startDate = BigInt(item.startDate?.toString() || '0')
      const nextBillingDate = BigInt(item.nextBillingDate?.toString() || '0')
      const endDate = BigInt(item.endDate?.toString() || '0')
      const currentUsage = BigInt(item.currentUsage?.toString() || '0')
      const totalPaid = BigInt(item.totalPaid?.toString() || '0')
      const createdAt = BigInt(item.createdAt?.toString() || '0')

      // 计算 isActive 状态 - 根据合约逻辑
      const isActive = 
        status === SubscriptionStatus.Active && 
        nextBillingDate + BigInt(3 * 24 * 60 * 60) > now // 3天宽限期

      const subscription: Subscription = {
        subscriptionId,
        planId,
        agentId,
        subscriber,
        status,
        startDate,
        nextBillingDate,
        endDate,
        currentUsage,
        totalPaid,
        createdAt,
        isActive
      }

      return subscription
    } catch (error) {
      console.warn('Failed to transform subscription data:', error)
      // 返回一个默认的无效订阅，确保类型正确
      const defaultSubscription: Subscription = {
        subscriptionId: BigInt(0),
        planId: BigInt(0),
        agentId: BigInt(0),
        subscriber: '0x0000000000000000000000000000000000000000',
        status: SubscriptionStatus.Expired,
        startDate: BigInt(0),
        nextBillingDate: BigInt(0),
        endDate: BigInt(0),
        currentUsage: BigInt(0),
        totalPaid: BigInt(0),
        createdAt: BigInt(0),
        isActive: false
      }
      return defaultSubscription
    }
  }).filter
